#include "alp/graph/predicates.hpp"
namespace alp::graph { GraphPredicateRegistry::GraphPredicateRegistry(){for(auto&s:{"node","edge","connected","reachable","path"}){if(s=="node")predicates_.insert({s,1});else predicates_.insert({s,2});}}bool GraphPredicateRegistry::supports(const alp::Predicate&p)const{return predicates_.contains(p);}std::set<alp::Predicate>GraphPredicateRegistry::predicates()const{return predicates_;}std::vector<alp::Atom> materialize_reachable(const Graph&g,const std::vector<std::pair<std::size_t,std::size_t>>&r){std::vector<alp::Atom>out;for(auto[i,j]:r)out.push_back({{"reachable",2},{alp::Term::constant(g.index().name(i)),alp::Term::constant(g.index().name(j))}});return out;} }
